        khach: str(draft["tenNguoiNhan"]) || str(thread.tenNguoi) || str(thread.nguoi),
        dienThoai: str(draft["dienThoai"]),
        diaChi: str(draft["diaChi"]),
        ghiChu: str(draft["ghiChu"]),
        nhan: "fanpage",
        ...thread.maKhach ? { maKhach: thread.maKhach } : {},
