      if (!r.ok) {
        status(line, r.viSao, "bad");
        return;
      }
      const wasEditing = this.editingPolicy !== "";
      this.policies = r.than?.chinhSach ?? this.policies;
      this.editingPolicy = "";
      this.drawPolicies();
