            this.metricCard("Đang còn hàng", h("div", { class: "value", id: "kdt-tc-con" }, "0"), "Theo tick thủ công"),
            this.metricCard("Có ảnh đại diện", h("div", { class: "value", id: "kdt-tc-anh" }, "0"), "Ảnh local/ảnh đã import")
