        sizeQuen: v("profileUsualSize"),
        formChan: v("profileFootForm"),
        monChoi: v("profileSportsUse"),
        brandThich: v("profilePreferredBrands"),
        daMua: v("profilePurchasedProducts"),
        tomTat: v("profileSummary")
